INSERT INTO track_curated (circuit_id, characteristics, updated_at) VALUES
  ('albert_park',    'Полугородская трасса вокруг озера Альберт-Парк, сочетание быстрых участков и медленных шиканов; после реконфигурации 2022 года стала быстрее и с меньшим числом торможений.', CURRENT_TIMESTAMP),
  ('shanghai',       'Длинная задняя прямая и характерный "улиточный" комплекс поворотов 1–3 с постепенно сужающимся радиусом; разнообразие типов поворотов создаёт повышенную нагрузку на шины.', CURRENT_TIMESTAMP),
  ('suzuka',         'Единственная трасса календаря с пересечением собственной трассы "восьмёркой"; скоростной участок S-образных поворотов считается одним из самых технически требовательных для баланса машины.', CURRENT_TIMESTAMP),
  ('miami',          'Городская трасса вокруг стадиона Hard Rock, сочетание быстрых и технических секций; типична жаркая и влажная погода.', CURRENT_TIMESTAMP),
  ('villeneuve',     'Полугородская трасса на острове Нотр-Дам с длинными прямыми и жёсткими зонами торможения (включая "Стену чемпионов"); низкое сцепление покрытия, высокая нагрузка на тормоза.', CURRENT_TIMESTAMP),
  ('monaco',         'Самая медленная и тесная уличная трасса календаря, обгоны крайне затруднены — результат гонки почти полностью решает квалификация.', CURRENT_TIMESTAMP),
  ('catalunya',      'Классическая "универсальная" трасса с длинными быстрыми поворотами; долгое время использовалась для предсезонных тестов, требовательна к шинам на высокоскоростных виражах.', CURRENT_TIMESTAMP),
  ('red_bull_ring',  'Короткая высокогорная трасса с заметным перепадом высот, немного поворотов, высокие скорости с жёсткими зонами торможения.', CURRENT_TIMESTAMP),
  ('silverstone',    'Быстрая, "текучая" трасса на месте бывшего аэродрома; знаменита скоростными поворотами (Copse, связка Maggotts-Becketts), требовательна к аэродинамике и шинам.', CURRENT_TIMESTAMP),
  ('spa',            'Самая длинная трасса календаря, значительные перепады высот, культовая связка Eau Rouge/Raidillon; погода нередко различается на разных участках трассы.', CURRENT_TIMESTAMP),
  ('hungaroring',    'Тесная, извилистая трасса, которую называют "Монако без стен"; низкая средняя скорость, обгоны затруднены, требует высокой прижимной силы.', CURRENT_TIMESTAMP),
  ('zandvoort',      'Компактная прибрежная трасса с наклонными виражами — самый заметный из них финальный поворот; узкая, с "олдскульным" характером.', CURRENT_TIMESTAMP),
  ('monza',          '"Храм скорости" — минимальная прижимная сила из всех трасс календаря, длинные прямые и шиканы, самые высокие скорости сезона.', CURRENT_TIMESTAMP),
  ('madring',        'Новая гибридная трасса 2026 года вокруг выставочного центра IFEMA, сочетает тесные городские участки с быстрым постоянным сектором; отличительная черта — 500-метровый вираж La Monumental с уклоном около 24%.', CURRENT_TIMESTAMP),
  ('baku',           'Уличная трасса, сочетающая одну из самых длинных прямых календаря с крайне узким и тесным участком вокруг Старого города; высокие максимальные скорости при повышенном риске аварий из-за близости стен.', CURRENT_TIMESTAMP),
  ('sepang',         'Широкая трасса с длинными прямыми и затяжными поворотами; исторически жаркий и влажный тропический климат.', CURRENT_TIMESTAMP),
  ('marina_bay',     'Уличная трасса, ночная гонка, высокая влажность и большое число поворотов; одна из самых физически изматывающих гонок сезона из-за жары и продолжительности.', CURRENT_TIMESTAMP),
  ('americas',       'Построена с нуля, заметный перепад высот (затяжной подъём на первом повороте), сочетает элементы, вдохновлённые другими известными трассами мира.', CURRENT_TIMESTAMP),
  ('rodriguez',      'Трасса на большой высоте над уровнем моря — разрежённый воздух влияет на аэродинамику и охлаждение двигателя; длинная прямая ведёт в стадионную секцию Foro Sol.', CURRENT_TIMESTAMP),
  ('interlagos',     'Трасса с движением против часовой стрелки и перепадами высот, переменчивая погода; исторически часто становится ареной непредсказуемых гонок.', CURRENT_TIMESTAMP),
  ('vegas',          'Уличная трасса на Стрипе, очень длинные прямые, ночная гонка в прохладную погоду — одни из самых высоких скоростей календаря.', CURRENT_TIMESTAMP),
  ('losail',         'Быстрая, "текучая" трасса, изначально построенная для MotoGP; ночная гонка под прожекторами, продолжительные скоростные повороты создают высокую нагрузку на шины.', CURRENT_TIMESTAMP),
  ('yas_marina',     'Современная трасса с сочетанием длинных прямых и технической секции у марины; принимает финал сезона, гонка стартует днём и заканчивается ночью.', CURRENT_TIMESTAMP);
